import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct {
	LrAcct      string
	LrPrincipal decimal.Decimal
	LrRate      decimal.Decimal
	LrYears     int64
}

var WsEofFlag string = "N"
var WsInterest decimal.Decimal = decimal.NewFromInt(0)
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsPrinEd string
var WsIntEd string
var WsTotalEd string

var loanFileLines []string
var loanFileIndex int
var currentLoanRec LoanRec
var InputDone bool

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func formatEdited(picture string, val decimal.Decimal) string {
	// split picture into integer and fractional parts
	dotIdx := strings.Index(picture, ".")
	intPic := picture
	fracPic := ""
	fracLen := 0
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
		fracLen = len(fracPic)
	}
	intWidth := len(intPic)

	// count digit slots in integer picture
	intDigitSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigitSlots++
		}
	}

	// get decimal string with required fractional digits, rounded to fracLen
	// Use StringFixed to get rounded representation (MOVE already handled scale)
	// For formatting we want rounding to picture scale; use Round
	rounded := val.Round(int32(fracLen))
	// handle negative
	neg := rounded.IsNegative()
	if neg {
		rounded = rounded.Abs()
	}
	s := rounded.StringFixed(int32(fracLen))
	// s like "1234.56" or "0.00" if fracLen>0 else "1234"
	var intDigits string
	var fracDigits string
	if fracLen > 0 {
		parts := strings.SplitN(s, ".", 2)
		intDigits = parts[0]
		if len(parts) > 1 {
			fracDigits = parts[1]
		} else {
			fracDigits = strings.Repeat("0", fracLen)
		}
		// pad fracDigits
		if len(fracDigits) < fracLen {
			fracDigits = fracDigits + strings.Repeat("0", fracLen-len(fracDigits))
		} else if len(fracDigits) > fracLen {
			fracDigits = fracDigits[:fracLen]
		}
	} else {
		intDigits = s
		// remove possible dot
		if idx := strings.Index(intDigits, "."); idx >= 0 {
			intDigits = intDigits[:idx]
		}
	}
	if intDigits == "" {
		intDigits = "0"
	}
	// Truncate high-order digits if too many
	if len(intDigits) > intDigitSlots {
		intDigits = intDigits[len(intDigits)-intDigitSlots:]
	}
	// left pad with zeros to fill digit slots
	if len(intDigits) < intDigitSlots {
		intDigits = strings.Repeat("0", intDigitSlots-len(intDigits)) + intDigits
	}

	// Build integer output array
	outRunes := []rune(intPic)
	// map slot index to position in outRunes
	// First create padded digits array
	paddedDigits := intDigits // length == intDigitSlots

	// Determine firstNonZero index among padded digits
	firstNonZero := -1
	for i, c := range paddedDigits {
		if c != '0' {
			firstNonZero = i
			break
		}
	}
	if firstNonZero == -1 {
		// value zero: keep last digit (the mandatory 9)
		firstNonZero = intDigitSlots - 1
	}
	// Also need to respect '9' mandatory: suppression should not go beyond last 9?
	// But firstNonZero already points to last slot for zero case.
	// For non-zero, if there are 9's before firstNonZero, they should still be suppressed? In COBOL Z before 9: leading zeros suppressed even though 9 would normally show zero, but suppression due to leading zeros still applies until first non-zero.
	// So firstNonZero logic is correct: suppress all Z slots before first non-zero, but 9 slots beyond suppression show digit (which they do).

	slotIdx := 0
	for i, r := range outRunes {
		if r == 'Z' || r == '9' {
			ch := rune(paddedDigits[slotIdx])
			if slotIdx < firstNonZero {
				ch = ' '
			}
			outRunes[i] = ch
			slotIdx++
		} else if r == ',' {
			// comma suppressed if next slot is still in suppressed region
			// Find next slot index (which is slotIdx)
			if slotIdx <= firstNonZero && firstNonZero != intDigitSlots-1 || slotIdx < firstNonZero {
				// More precise: if slotIdx <= firstNonZero and the digit at firstNonZero is beyond this comma,
				// For general, comma is suppressed if all slots before next comma are suppressed.
				// That is slotIdx <= firstNonZero ? Actually if slotIdx == firstNonZero+1 means next digit is first non-zero, comma should be kept? But in typical editing, commas before first non-zero become spaces.
				// So: if slotIdx <= firstNonZero, comma is in suppressed zone -> space
				// Need to handle case where firstNonZero is 0 -> no suppressed comma before it.
			}
			// simplified rule:
			if slotIdx <= firstNonZero {
				// Need to check if firstNonZero == intDigitSlots-1 and value zero, all commas suppressed
				// Otherwise, commas before firstNonZero are spaces
				// Determine if comma is before firstNonZero slot
				// slotIdx is index of next digit slot
				// If next digit slot index <= firstNonZero => this comma is before or at suppression boundary
				// Example: picture Z,ZZZ,ZZ9 with digits 0001000, firstNonZero=3 (digit '1')
				// intPic = "Z,ZZZ,ZZ9"
				// positions: 0:Z(slot0),1:,,2:Z(slot1),3:Z(slot2),4:Z(slot3),5:,,6:Z(slot4),7:Z(slot5),8:9(slot6)
				// For comma at pos1, slotIdx=1, firstNonZero=3 => 1<=3 => space correct
				// For comma at pos5, slotIdx=4, 4<=3? false => keep comma correct (result "    1,000")
				outRunes[i] = ' '
			} else {
				outRunes[i] = ','
			}
		}
	}

	intPart := string(outRunes)
	if dotIdx >= 0 {
		result := intPart + "." + fracDigits
		// ensure length matches picture (should)
		if len(result) < len(picture) {
			result = strings.Repeat(" ", len(picture)-len(result)) + result
		}
		if neg {
			// not needed for this program
		}
		return result
	}
	return intPart
}

func moveToEdited(pic string, v decimal.Decimal) string {
	return formatEdited(pic, v)
}

func truncateToScale(v decimal.Decimal, scale int32) decimal.Decimal {
	return v.Truncate(scale)
}

func main() {
	// Open input.dat LINE SEQUENTIAL
	f, err := os.Open("input.dat")
	if err != nil {
		// if file doesn't exist, treat as empty
		loanFileLines = []string{}
	} else {
		defer f.Close()
		scanner := bufio.NewScanner(f)
		// allow long lines
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, 10*1024*1024)
		for scanner.Scan() {
			line := scanner.Text()
			// remove trailing \r if present (Scanner already strips \n, but \r remains if CRLF not fully handled)
			if len(line) > 0 && line[len(line)-1] == '\r' {
				line = line[:len(line)-1]
			}
			loanFileLines = append(loanFileLines, line)
		}
		if err := scanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	}
	loanFileIndex = 0
	WsEofFlag = "N"
	InputDone = false

	MAINPARA()
}

func MAINPARA() {
	// OPEN INPUT LOAN-FILE
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	// CLOSE LOAN-FILE
	SUMMARYPARA()
}

func READPARA() {
	if loanFileIndex >= len(loanFileLines) {
		WsEofFlag = "Y"
		InputDone = true
		return
	}
	raw := loanFileLines[loanFileIndex]
	loanFileIndex++
	// pad with spaces on right to 21
	if len(raw) < 21 {
		raw = raw + strings.Repeat(" ", 21-len(raw))
	} else if len(raw) > 21 {
		raw = raw[:21]
	}
	// parse
	acct := raw[0:6]
	prinStr := raw[6:15]
	rateStr := raw[15:19]
	yearsStr := raw[19:21]

	// parse numeric fields: digits only, implied decimal
	prinVal := parseImplied(prinStr, 2)
	rateVal := parseImplied(rateStr, 2)
	var yearsVal int64
	yearsVal = parseInt(yearsStr)

	currentLoanRec = LoanRec{
		LrAcct:      acct,
		LrPrincipal: prinVal,
		LrRate:      rateVal,
		LrYears:     yearsVal,
	}
}

func parseImplied(s string, scale int32) decimal.Decimal {
	// s contains digits (and possibly spaces). Treat spaces as 0? COBOL numeric DISPLAY would be digits; we trim spaces.
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.NewFromInt(0)
	}
	// remove any non-digit
	// Keep digits and sign
	clean := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			clean += string(ch)
		} else if ch == '-' || ch == '+' {
			clean += string(ch)
		}
	}
	if clean == "" || clean == "+" || clean == "-" {
		return decimal.NewFromInt(0)
	}
	neg := false
	if clean[0] == '-' {
		neg = true
		clean = clean[1:]
	} else if clean[0] == '+' {
		clean = clean[1:]
	}
	// strip leading zeros but keep at least one
	d, ok := decimal.NewFromString(clean)
	if !ok {
		d = decimal.NewFromInt(0)
	}
	d = decimal.New(d.IntPart(), -scale)
	if neg {
		d = d.Neg()
	}
	return d
}

func parseInt(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	var v int64
	fmt.Sscan(s, &v)
	return v
}

func PROCESSPARA() {
	// COMPUTE WS-INTEREST ROUNDED = LR-PRINCIPAL * LR-RATE * LR-YEARS / 100
	// Use decimal arithmetic, then round to 2
	tmp := currentLoanRec.LrPrincipal.Mul(currentLoanRec.LrRate).Mul(decimal.NewFromInt(currentLoanRec.LrYears))
	tmp = tmp.Shift(-2) // divide by 100
	WsInterest = tmp.Round(2)
	// handle overflow truncation to PIC 9(9)V99 : keep low-order digits if needed (not needed for tests, but implement)
	WsInterest = enforcePicture(WsInterest, 9, 2)

	WsTotal = WsTotal.Add(WsInterest)
	WsTotal = enforcePicture(WsTotal, 11, 2)

	WsCount++
	// enforce 9(5) overflow
	if WsCount > 99999 {
		WsCount = WsCount % 100000
	}

	WsPrinEd = moveToEdited("Z,ZZZ,ZZ9.99", currentLoanRec.LrPrincipal)
	WsIntEd = moveToEdited("ZZZ,ZZZ,ZZ9.99", WsInterest)
	// DISPLAY LR-ACCT " " WS-PRIN-ED " " WS-INT-ED
	fmt.Printf("%s %s %s\n", currentLoanRec.LrAcct, WsPrinEd, WsIntEd)
	READPARA()
}

func enforcePicture(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// Truncate/round already done; enforce low-order truncation if exceeds picture
	// Picture allows intDigits integer digits and scale fractional digits
	// If value exceeds, keep only low-order intDigits digits
	v = v.Truncate(scale)
	// Determine modulus = 10^(intDigits+scale) ??? Need to keep scale fractional part
	// We keep value mod 10^intDigits for integer part
	// Compute integer part overflow
	// modulus = 10^intDigits
	modInt := decimal.New(1, int32(intDigits)) // 10^intDigits
	// Separate sign
	neg := v.IsNegative()
	abs := v.Abs()
	intPart := abs.Truncate(0)
	fracPart := abs.Sub(intPart)
	if intPart.Cmp(modInt) >= 0 {
		// keep low-order digits: intPart mod modInt
		intPart = intPart.Mod(modInt)
		abs = intPart.Add(fracPart)
		if neg {
			abs = abs.Neg()
		}
		v = abs
	}
	return v
}

func SUMMARYPARA() {
	WsTotalEd = moveToEdited("ZZ,ZZZ,ZZZ,ZZ9.99", WsTotal)
	// DISPLAY "RECORDS: " WS-COUNT  (WS-COUNT is PIC 9(5) zero-padded)
	countStr := fmt.Sprintf("%05d", WsCount)
	fmt.Printf("RECORDS: %s\n", countStr)
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

